// Dữ liệu vào: header bí mật và identity kỹ thuật của một bài Progress Log.
// Việc chính: xác thực nguồn gửi, kiểm tra ID và tự tính lại bốn lớp identity.
// Kết quả: gói sạch để đọc đúng lớp, học viên và buổi trên Portal.
// Khi lỗi: dừng trước khi gọi Portal; execution chỉ hiện mã lỗi chung.

const request = $input.first()?.json ?? {};
const headers = request.headers ?? {};
const supplied = String(headers['x-learning-attendance-sync'] ?? headers['X-Learning-Attendance-Sync'] ?? '');
const expectedSecret = String($vars.TERM_TEST_ERP_SYNC_SECRET ?? '');
function sameSecret(left, right) {
  if (!left || !right || left.length !== right.length) return false;
  let difference = 0;
  for (let index = 0; index < left.length; index += 1) difference |= left.charCodeAt(index) ^ right.charCodeAt(index);
  return difference === 0;
}
if (!sameSecret(supplied, expectedSecret)) throw new Error('ATTENDANCE_SYNC_UNAUTHORIZED');

const body = request.body ?? {};
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const submissionId = String(body.submissionId ?? '').toLowerCase();
const assignmentId = String(body.assignmentId ?? '').toLowerCase();
const studentRef = String(body.studentRef ?? '').toLowerCase();
const classId = String(body.classId ?? '');
const studentId = String(body.studentId ?? '');
const sessionNumber = Number(body.sessionNumber);
const commit = body.commit === true;
if (body.schemaVersion !== 'LearningPortalAttendanceJobV1' || body.attendanceStatus !== 'PRESENT') throw new Error('ATTENDANCE_SYNC_INVALID_SCHEMA');
if (![submissionId, assignmentId, studentRef].every(value => uuidPattern.test(value))) throw new Error('ATTENDANCE_SYNC_INVALID_UUID');
if (!/^\d+$/.test(classId) || !/^\d+$/.test(studentId) || !Number.isInteger(sessionNumber) || sessionNumber < 1 || sessionNumber > 100) throw new Error('ATTENDANCE_SYNC_INVALID_TARGET');
const identity = {
  entityKey: `student:${studentRef}`,
  unitKey: `portal-attendance:${assignmentId}:session:${sessionNumber}`,
  operationKey: `portal-attendance:${submissionId}:v1`,
  idempotencyKey: `portal-attendance:${submissionId}:enqueue:v1`
};
for (const [key, value] of Object.entries(identity)) {
  if (String(body[key] ?? '') !== value) throw new Error('ATTENDANCE_SYNC_IDENTITY_MISMATCH');
}
return [{ json: { submissionId, assignmentId, studentRef, classId, studentId, sessionNumber, commit, ...identity } }];

// Dữ liệu vào: danh sách buổi và bản ghi học viên từ Portal.
// Việc chính: tìm đúng buổi theo thứ tự thời gian, đọc trạng thái cũ và giữ nguyên bài tập/note.
// Kết quả: chỉ cho phép ghi PRESENT khi ô điểm danh còn trống; có trạng thái khác thì chuyển GV xem.
// Khi lỗi: dừng fail-closed, không ghi sang học viên hoặc buổi khác.

const identity = $('Xác thực và khóa identity').first().json;
const root = $input.first()?.json ?? {};
const rows = Array.isArray(root) ? root : Array.isArray(root.data) ? root.data : Array.isArray(root.data?.data) ? root.data.data : [];
const meta = root.meta ?? root.data?.meta ?? {};
const sessionsRaw = Array.isArray(meta.class_sessions) ? meta.class_sessions : Array.isArray(root.class_sessions) ? root.class_sessions : [];
const sessions = sessionsRaw.map(session => ({
  ...session,
  id: session.class_session_id ?? session.id,
  number: Number(session.session_number ?? session.sessionNumber ?? session.order ?? session.ordinal),
  startsAt: session.session_start_datetime ?? session.starts_at ?? session.start_datetime ?? ''
})).filter(session => session.id !== undefined && session.id !== null);
let target = sessions.find(session => Number.isInteger(session.number) && session.number === identity.sessionNumber);
if (!target) {
  const ordered = [...sessions].sort((left, right) => String(left.startsAt).localeCompare(String(right.startsAt)));
  target = ordered[identity.sessionNumber - 1];
}
if (!target) throw new Error('ATTENDANCE_SYNC_SESSION_NOT_FOUND');
const targetSessionId = String(target.id);
const current = rows.find(row => String(row.student_id) === identity.studentId && String(row.class_session_id) === targetSessionId) ?? null;
const currentStatus = current?.attendance_status === undefined || current?.attendance_status === null || current?.attendance_status === '' ? null : Number(current.attendance_status);
let status = 'preview';
let needsWrite = false;
if (currentStatus === 1) status = 'already_present';
else if (currentStatus !== null) status = 'conflict';
else if (identity.commit) { status = 'pending_write'; needsWrite = true; }
const requestBody = { student_class_sessions: [{
  student_id: Number(identity.studentId),
  class_session_id: Number(targetSessionId),
  attendance_status: 1,
  homework_status: current?.homework_status ?? null,
  note: current?.note ?? null
}] };
return [{ json: { ...identity, targetSessionId, status, needsWrite, requestBody } }];

// Dữ liệu vào: trạng thái Portal vừa đọc lại sau lệnh ghi.
// Việc chính: đối chiếu lại đúng student_id + class_session_id và attendance_status = PRESENT.
// Kết quả: chỉ trả synced khi Portal thực sự đã lưu đúng bản ghi.
// Khi lỗi: ném lỗi để backend retry, không báo thành công giả.

const decision = $('Chọn đúng buổi và quyết định').first().json;
const root = $input.first()?.json ?? {};
const rows = Array.isArray(root) ? root : Array.isArray(root.data) ? root.data : Array.isArray(root.data?.data) ? root.data.data : [];
const saved = rows.find(row => String(row.student_id) === decision.studentId && String(row.class_session_id) === decision.targetSessionId);
if (!saved || Number(saved.attendance_status) !== 1) throw new Error('ATTENDANCE_SYNC_READBACK_FAILED');
return [{ json: { ...decision, status: 'synced', needsWrite: false, requestBody: undefined } }];

// Dữ liệu vào: quyết định cuối cùng hoặc kết quả readback.
// Việc chính: loại requestBody và chỉ trả identity cùng trạng thái an toàn.
// Kết quả: backend có thể fail-closed nếu bất kỳ ID nào không khớp.
// Khi lỗi: workflow không tự suy đoán hay đổi identity.

const value = $input.first().json;
return [{ json: {
  ok: true,
  status: value.status,
  entityKey: value.entityKey,
  unitKey: value.unitKey,
  operationKey: value.operationKey,
  idempotencyKey: value.idempotencyKey,
  classId: value.classId,
  studentId: value.studentId,
  sessionNumber: value.sessionNumber
} }];
